#!/usr/bin/env bash
# The NetFlow dashboards are generated by tools/netflow/generate.mjs, the NOC dashboards by tools/build-noc-dashboards.py (Device
# Health, Network Overview) and tools/build-noc-command-center.py; the committed JSON is the deployed state.
# This proves the generators still reproduce the committed files (compared without the instance-specific id/version).
set -uo pipefail
cd "$(dirname "${BASH_SOURCE[0]}")/.."
T=$(mktemp -d); cp tools/netflow/generate.mjs "$T/"; mkdir -p "$T/tools/netflow"; mv "$T/generate.mjs" "$T/tools/netflow/"
(cd "$T" && node tools/netflow/generate.mjs >/dev/null) || { echo "[FAIL] generator crashed"; exit 1; }
FAIL=0
for f in "$T"/dashboards/netflow/*.json; do
  n=$(basename "$f")
  node -e '
const fs=require("fs");const sort=o=>Array.isArray(o)?o.map(sort):o&&typeof o==="object"?Object.fromEntries(Object.keys(o).sort().map(k=>[k,sort(o[k])])):o;
const norm=d=>{d=JSON.parse(JSON.stringify(d));delete d.id;delete d.version;return JSON.stringify(sort(d));};
const a=JSON.parse(fs.readFileSync(process.argv[1],"utf8")),b=JSON.parse(fs.readFileSync(process.argv[2],"utf8"));
process.exit(norm(a)===norm(b)?0:1);' "$f" "dashboards/netflow/$n" && echo "[PASS] $n reproduced" || { echo "[FAIL] $n differs"; FAIL=1; }
done
# NOC: each Python generator writes into <its repo>/dashboards/noc; run them in a scratch copy and compare byte for byte
mkdir -p "$T/noc/tools" "$T/noc/dashboards/noc"; cp tools/build-noc-dashboards.py tools/build-noc-command-center.py tools/build-noc-network-traffic.py "$T/noc/tools/"
for g in build-noc-dashboards.py build-noc-command-center.py build-noc-network-traffic.py; do (cd "$T/noc" && python3 "tools/$g" >/dev/null) || { echo "[FAIL] $g crashed"; FAIL=1; }; done
for f in dashboards/noc/*.json; do
  cmp -s "$f" "$T/noc/$f" && echo "[PASS] $(basename "$f") reproduced" || { echo "[FAIL] $(basename "$f") differs from its generator's output"; FAIL=1; }
done
rm -rf "$T"; exit $FAIL
